from sdata2 import lab,crowd,DOOR
D=dict
LORD=lambda x=110,s=1: f'<g transform="translate({x} 0) scale({s})" stroke="#111" stroke-width="2.5"><circle cy="50" r="14" fill="#4a7fd0"/><path d="M-14 34 h28 v-14 h-28z" fill="#ffd60a"/><path d="M-24 140 q-4 -60 24 -76 q28 16 24 76z" fill="#ffd60a"/></g>'
FLUTE='<path d="M90 80 l50 -14" stroke="#7a5a3a" stroke-width="5"/>'
BOW='<path d="M160 40 q30 50 0 100" fill="none" stroke="#7a5a3a" stroke-width="5"/><path d="M160 40 v100" stroke="#111"/>'
V=[
D(n='1',lines=[['kamalākucacūcukakuṅkumato','niyatāruṇitātulanīlatano |'],['kamalāyatalocana lokapate','vijayībhava veṅkaṭaśailapate ‖1‖']],theme='VICTORY TO THE LORD OF VEṄKAṬA',
 svg=svg('The dark blue Lord with a reddish glow of kumkum on his chest beside Lakshmi, with lotus eyes',SUN(110,70,46).replace('#ffd60a','#ffe9a0')+LORD(110)+'<circle cx="104" cy="96" r="9" fill="#e63946" opacity=".8"/>'+lab(110,158,'VIJAYĪ BHAVA!',11),B),
 mean='O Lord whose incomparable dark-blue body is always tinged red by the kuṅkuma from Lakṣmī\'s embrace; O lotus-eyed Lord of the worlds: victory to You, O Lord of the Veṅkaṭa hill!',
 plain='Dark-blue Lord, reddened by Lakṣmī\'s kuṅkuma as she holds You close, lotus-eyed Lord of all the worlds: victory to You, Lord of Veṅkaṭa!',
 words=[('kamalā','<b>Lakṣmī</b>'),('kuṅkumataḥ','<b>from the kuṅkuma</b> (of her embrace)'),('aruṇita','<b>reddened</b>'),('atula-nīla-tano','<b>of incomparable dark-blue body</b>'),('āyata-locana','<b>long-eyed</b>, lotus-eyed'),('vijayī bhava','<b>be victorious!</b>')],
 deep='<p><b>Now He is awake.</b> The Suprabhātam woke the Lord; the Stotram ("hymn of praise") greets Him awake. The first word is <i>Kamalā</i>, Lakṣmī, just as the Suprabhātam began with the Mother in verse 3.</p><p><b>Blue and red.</b> The Lord\'s body is dark blue like a rain cloud; the red of kuṅkuma from Lakṣmī\'s embrace marks His chest. The colour picture says: He is never without Her.</p><p><b>A new rhythm.</b> Verses 1–8 are in <b>toṭaka</b> metre: short, quick lines of four beats, da-da-DUM ×4, like a march.</p>',
 cards=('💡 Toṭaka','A brisk 12-syllable metre; Śaṅkara\'s disciple Toṭaka is named after it.','💡 Kuṅkuma','Red powder worn by married women, a sign of auspiciousness.'),
 inner='The Lord is never without Lakṣmī; grace is never far from Him.',
 talk=('Why is the blue Lord red?','Lakṣmī\'s kuṅkuma! She\'s always on His chest, so its red always marks Him. Never apart.'),
 key='"Vijayī bhava": <b>victory to the Lord of Veṅkaṭa</b>.'),
D(n='2',lines=[['sacaturmukhaṣaṇmukhapañcamukha-','pramukhākhiladaivatamaulimaṇe |'],['śaraṇāgatavatsala sāranidhe','paripālaya māṃ vṛṣaśailapate ‖2‖']],theme='CROWN-JEWEL OF ALL GODS',
 svg=svg('A crown with a jewel at its centre held above gods with four, six and five faces',
  '<path d="M60 70 l10 -30 l20 20 l20 -30 l20 30 l20 -20 l10 30z" fill="#ffd60a" stroke="#111" stroke-width="3"/><circle cx="110" cy="56" r="9" fill="#1d6fb8" stroke="#111" stroke-width="2"/>'+crowd(['#e63946','#ff8c1a','#bcd4f0'],60,50,144,.55)+lab(60,158,'4 FACES',7)+lab(110,158,'6 FACES',7)+lab(160,158,'5 FACES',7),B),
 mean='O crest-jewel of all the gods, led by four-faced Brahmā, six-faced Kārttikeya and five-faced Śiva; O One who loves those who surrender to You, treasure-house of all that is best: protect me, O Lord of Vṛṣa hill.',
 plain='You are the jewel on the crowns of all the gods, Brahmā, Kārttikeya and Śiva included; You love all who come to You: please protect me, Lord of the hills.',
 words=[('catur-mukha','<b>four-faced</b>: Brahmā'),('ṣaṇ-mukha','<b>six-faced</b>: Kārttikeya'),('pañca-mukha','<b>five-faced</b>: Śiva'),('mauli-maṇe','<b>O crown-jewel</b>'),('śaraṇāgata-vatsala','<b>loving to those who surrender</b>'),('paripālaya mām','<b>protect me</b>')],
 deep='<p><b>The first request.</b> In the Suprabhātam the poet asked nothing; here, in verse 2, he asks: <i>paripālaya mām</i>, "protect me". Praise turns personal.</p><p><b>Vatsala.</b> The love of a cow for her calf, which licks it clean without minding the dirt. The Lord loves those who surrender in the same way, faults and all. <i>Vātsalya</i> is one of the qualities Śrīvaiṣṇavas most cherish in the Lord.</p><p><b>Crown-jewel.</b> The other gods bow to Him, so He is the jewel at the top of their crowns.</p>',
 cards=('💡 Vātsalya','A mother cow\'s love for her calf: love that overlooks faults.','💡 Śaraṇāgata','"One who has come for refuge": the surrendered devotee.'),
 inner='You don\'t need to be clean to come to Him. A mother cow licks the calf clean.',
 talk=('What does vatsala mean?','The love of a cow for her calf. She doesn\'t mind the mud; she licks it off. That\'s how He loves those who come to Him.'),
 key='Crown-jewel of the gods, <b>loving to all who seek refuge</b>.'),
D(n='3',lines=[['ativelatayā tava durviṣahair','anuvelakṛtair aparādhaśataiḥ |'],['bharitaṃ tvaritaṃ vṛṣaśailapate','parayā kṛpayā paripāhi hare ‖3‖']],theme='SAVE ME, IN SPITE OF MY FAULTS',
 svg=svg('A person kneeling under a heavy sack of mistakes, with a shining hand reaching down from the temple',TEMPLE(180,60)+'<path d="M170 70 q-30 20 -60 30" stroke="#ffd60a" stroke-width="8" fill="none"/>'+person(70,140,'#ff8c1a','#f2c79b',.65)+'<path d="M40 90 q30 -40 60 0 v20 h-60z" fill="#8a6a4a" stroke="#111" stroke-width="2"/>'+lab(70,100,'×100',10),B),
 mean='I am weighed down by hundreds of offences, committed again and again, beyond all limits, unbearable to You. Quickly, O Lord of Vṛṣa hill, protect me with Your supreme compassion, O Hari!',
 plain='I have done wrong hundreds of times, over and over, more than You could bear. Lord of the hills, please save me quickly, out of Your great mercy.',
 words=[('ati-velatayā','<b>beyond all limits</b>'),('durviṣahaiḥ','<b>unbearable</b>'),('anu-vela-kṛtaiḥ','<b>done again and again</b>'),('aparādha-śataiḥ','<b>by hundreds of offences</b>'),('tvaritam','<b>quickly</b>'),('parayā kṛpayā','<b>with supreme compassion</b>')],
 deep='<p><b>An honest confession.</b> The poet does not plead innocence. He admits hundreds of offences, again and again. His only argument is the Lord\'s <i>kṛpā</i>, mercy.</p><p><b>Quickly!</b> <i>Tvaritam</i>: the devotee does not want to wait. Like a child calling its mother, he asks for help now.</p><p><b>Not merit but mercy.</b> This is the Śrīvaiṣṇava view of salvation: we are saved by His grace, not earned by our record. Part 4, the Prapatti, will make this a formal surrender.</p>',
 cards=('💡 Aparādha','An offence, especially against the Lord or His devotees.','💡 Kṛpā','Compassion, mercy: the Lord\'s grace freely given.'),
 inner='Don\'t hide your faults from the Lord. Name them, and ask for mercy.',
 talk=('He admits hundreds of mistakes?','Honestly, yes. He doesn\'t argue his case; he just asks for mercy, quickly!'),
 key='Not my merit but <b>His mercy</b>.'),
D(n='4',lines=[['adhiveṅkaṭaśailam udāramater','janatābhimatādhikadānaratāt |'],['paradevatayā gaditān nigamaiḥ','kamalādayitān na paraṃ kalaye ‖4‖']],theme='NONE HIGHER THAN LAKṢMĪ\'S BELOVED',
 svg=svg('The Lord on top of the Venkata hill giving gifts that overflow beyond what the people below hold out their hands for',HILL+TEMPLE(110,84)+crowd(['#ff8c1a','#1d6fb8','#e05a8a','#2a9d6f'],40,46,152,.45)+''.join(f'<circle cx="{60+30*k}" cy="{100+(k%2)*8}" r="5" fill="#ffd60a" stroke="#111"/>' for k in range(4))+lab(110,24,'MORE THAN THEY ASK',10),B),
 mean='Generous-hearted, He lives on the Veṅkaṭa hill and delights in giving people more than they wish for; the Vedas declare Him the Supreme Deity. I consider nothing higher than the beloved of Kamalā.',
 plain='The Lord on Veṅkaṭa hill gives people more than they ask for, and the Vedas call Him the Supreme God. For me there is nothing higher than Lakṣmī\'s beloved.',
 words=[('adhi-veṅkaṭa-śailam','<b>on the Veṅkaṭa hill</b>'),('udāra-mateḥ','<b>generous-hearted</b>'),('abhimata-adhika-dāna','<b>giving more than desired</b>'),('para-devatā','<b>Supreme Deity</b>'),('nigamaiḥ','<b>by the Vedas</b>'),('na param kalaye','<b>I consider none higher</b>')],
 deep='<p><b>A refrain of faith.</b> Verses 4 and 5 both end <i>na paraṃ kalaye</i>, "I see none higher". The poet states his choice of God plainly.</p><p><b>More than asked.</b> The Lord of Tirumala is famous for granting wishes; the verse says He gives <i>more</i> than people want. That generosity is His nature (<i>udāra</i>).</p><p><b>Kamalā-dayita.</b> "Beloved of Lakṣmī": once again He is named through the Goddess.</p>',
 cards=('💡 Nigama','A name for the Vedas: "that which has come down".','💡 Kaliyuga Varada','A title of Veṅkaṭeśvara: the boon-giver of the Kali age.'),
 inner='Ask the Lord, but don\'t limit Him: He gives more than we know to ask.',
 talk=('"None higher": isn\'t that strong?','It\'s the poet\'s own choice of God, said with love. And the reason he gives: the Lord gives more than anyone asks.'),
 key='He gives more than we ask: <b>none higher than Lakṣmī\'s beloved</b>.'),
D(n='5',lines=[['kalaveṇuravāvaśagopavadhū-','śatakoṭivṛtāt smarakoṭisamāt |'],['prativallavikābhimatāt sukhadāt','vasudevasutān na paraṃ kalaye ‖5‖']],theme='NONE HIGHER THAN KṚṢṆA',
 svg=svg('Krishna playing the flute in a circle of dancing cowherd girls under the moon',
  '<circle cx="180" cy="30" r="14" fill="#fff8c0" stroke="#111"/>'+''.join(person(110+70*__import__("math").cos(k*1.047),118+20*__import__("math").sin(k*1.047),'#e05a8a','#f2c79b',.38) for k in range(6))+'<g stroke="#111" stroke-width="2"><circle cx="110" cy="86" r="10" fill="#4a7fd0"/><path d="M96 130 q14 -40 28 0z" fill="#ffd60a"/></g><path d="M116 94 l30 -8" stroke="#7a5a3a" stroke-width="4"/>'+lab(60,26,'RĀSA',11),B),
 mean='Surrounded by countless cowherd women spellbound by the sweet sound of His flute; as handsome as millions of Kāmas; loved by each cowherd girl; giver of joy: I consider nothing higher than the son of Vasudeva.',
 plain='Kṛṣṇa, whose flute enchants countless gopīs, more beautiful than any god of love, dear to every one of them, giver of joy: for me there is nothing higher.',
 words=[('kala-veṇu-rava','<b>the sweet sound of the flute</b>'),('avaśa','<b>helpless</b>, spellbound'),('gopa-vadhū','<b>cowherd women</b>'),('smara-koṭi-samāt','<b>equal to millions of Kāmas</b>'),('prati-vallavikā','<b>each cowherd girl</b>'),('vasudeva-suta','<b>son of Vasudeva</b>: Kṛṣṇa')],
 deep='<p><b>Kṛṣṇa of Vṛndāvana.</b> The poet now sees the Lord of the hills as Kṛṣṇa, playing His flute among the gopīs. The scene is the rāsa dance of the Bhāgavata Purāṇa, where Kṛṣṇa seems present to every gopī at once.</p><p><b>Each one his own.</b> <i>Prati-vallavikā-abhimata</i>: "dear to each cowherd girl". Every devotee feels the Lord is especially theirs.</p><p><b>Same refrain.</b> Like verse 4: "I see none higher". The Lord of Veṅkaṭa and Kṛṣṇa are one.</p>',
 cards=('💡 Gopī','The cowherd women of Vraja, models of selfless love for Kṛṣṇa.','💡 Rāsa-līlā','Kṛṣṇa\'s moonlit circle dance with the gopīs, told in Bhāgavatam book 10.'),
 inner='To each devotee the Lord is wholly their own, and wholly everyone\'s.',
 talk=('Now it\'s Kṛṣṇa?','The same Lord! The poet sees the flute-player of Vṛndāvana standing on the Seven Hills.'),
 key='The flute-player of Vṛndāvana: <b>none higher than Kṛṣṇa</b>.',
 note='Some texts read prati-pallavikā for prati-vallavikā.'),
D(n='6',lines=[['abhirāmaguṇākara dāśarathe','jagadekadhanurdhara dhīramate |'],['raghunāyaka rāma rameśa vibho','varado bhava deva dayājaladhe ‖6‖']],theme='O RĀMA, OCEAN OF KINDNESS',
 svg=svg('Rama standing with his great bow, calm and kind, with an ocean behind him',
  '<rect x="0" y="110" width="220" height="50" fill="#4aa3df"/>'+''.join(f'<path d="M{20*k} 112 q10 -8 20 0" fill="none" stroke="#1d6fb8" stroke-width="3"/>' for k in range(11))+'<g stroke="#111" stroke-width="2.5"><circle cx="110" cy="50" r="13" fill="#2a9d6f"/><path d="M98 36 h24 v-12 h-24z" fill="#ffd60a"/><path d="M90 130 q-4 -50 20 -66 q24 16 20 66z" fill="#ffd60a"/></g><path d="M140 40 q24 44 0 90" fill="none" stroke="#7a5a3a" stroke-width="5"/><path d="M140 40 v90" stroke="#111"/>'+lab(110,152,'DĀŚARATHI',10),B),
 mean='O mine of delightful virtues, son of Daśaratha; the one great archer of the world, steady of mind; O leader of the Raghus, Rāma, Lord of Ramā, all-pervading: be my giver of boons, O God, ocean of compassion.',
 plain='Rāma, son of Daśaratha, full of lovely virtues, the world\'s greatest archer, calm and wise, husband of Lakṣmī: grant me Your blessing, ocean of kindness.',
 words=[('abhirāma-guṇa-ākara','<b>mine of delightful virtues</b>'),('dāśarathe','<b>O son of Daśaratha</b>'),('dhanur-dhara','<b>bow-bearer</b>, archer'),('dhīra-mate','<b>of steady mind</b>'),('raghu-nāyaka','<b>leader of the Raghus</b>'),('dayā-jaladhe','<b>O ocean of compassion</b>')],
 deep='<p><b>Back to Rāma.</b> The Suprabhātam began with Rāma (verse 1). The Stotram now gives three verses (6–8) to Him.</p><p><b>Rameśa.</b> "Lord of Ramā": Ramā is Lakṣmī. Rāma\'s Sītā is Lakṣmī Herself; so Rāma is again the beloved of Lakṣmī.</p><p><b>Dhīra.</b> Rāma\'s calm in exile and war is the steadiness the devotee prays for.</p>',
 cards=('💡 Dāśarathi','"Son of Daśaratha": a name of Rāma.','💡 Raghu-vaṃśa','The solar dynasty of Raghu, into which Rāma was born.'),
 inner='Steadiness of mind is a gift worth asking for.',
 talk=('Why so much Rāma now?','The hymn began with Rāma\'s morning. Now three verses praise Him: the archer, the steady one, the ocean of kindness.'),
 key='O Rāma, archer of the world: <b>be my giver of blessings</b>.'),
D(n='7',lines=[['avanītanayākamanīyakaraṃ','rajanīkaracārumukhāmburuham |'],['rajanīcararājatamomihiraṃ','mahanīyam ahaṃ raghurāmam aye ‖7‖']],theme='RĀMA, THE SUN AGAINST RĀVAṆA\'S DARKNESS',
 svg=svg('Rama holding Sita\'s hand, with a sun behind him driving away a dark cloud shaped like a ten-headed demon',SUN(170,50,22)+'<path d="M10 40 q30 -30 60 0 q20 -10 30 10 q-40 20 -90 -10z" fill="#333" stroke="#111"/>'+person(80,140,'#2a9d6f','#2a9d6f',.7)+person(120,140,'#e05a8a','#f2c79b',.7)+'<path d="M92 108 h16" stroke="#111" stroke-width="3"/>'+lab(50,64,'TAMAS',9),B),
 mean='I go to Raghurāma, worthy of all honour: who holds the lovely hand of the Earth\'s daughter; whose lotus face is as charming as the moon; who is the sun that dispelled the darkness, the king of the night-walkers.',
 plain='I worship Rāma, who holds Sītā\'s hand, whose face shines like the moon, and who drove away Rāvaṇa\'s darkness like the sun.',
 words=[('avanī-tanayā','<b>daughter of the Earth</b>: Sītā'),('kamanīya-karam','<b>whose hand is lovely</b>'),('rajanī-kara','<b>night-maker</b>: the moon'),('rajanī-cara-rāja','<b>king of night-walkers</b>: Rāvaṇa'),('tamo-mihiram','<b>sun to the darkness</b>'),('aye','<b>I approach</b>, I go to')],
 deep='<p><b>Sun and moon.</b> A playful pair: Rāma\'s face is lovely as the moon, yet He is the sun that drives off Rāvaṇa, the king of "night-walkers" (rākṣasas).</p><p><b>Sītā, Earth\'s daughter.</b> Sītā was found in a furrow by King Janaka; so she is <i>avanī-tanayā</i>, daughter of the Earth.</p><p><b>Holding her hand.</b> The image is of Rāma\'s wedding, <i>pāṇi-grahaṇa</i>, "taking the hand", and again of Lord and Goddess together.</p>',
 cards=('💡 Pāṇi-grahaṇa','"Taking the hand": the key rite of a Hindu wedding.','💡 Rākṣasa','Night-walking demons of the epics; Rāvaṇa was their king.'),
 inner='Light does not argue with darkness. It simply rises.',
 talk=('Moon and sun at once?','His face is gentle as the moon for Sītā, and fierce as the sun for Rāvaṇa\'s darkness. Both are Rāma.'),
 key='Moon-faced for Sītā, <b>a sun to Rāvaṇa\'s darkness</b>.'),
D(n='8',lines=[['sumukhaṃ suhṛdaṃ sulabhaṃ sukhadaṃ','svanujaṃ ca sukāyam amoghaśaram |'],['apahāya raghūdvaham anyam ahaṃ','na kathañcana kañcana jātu bhaje ‖8‖']],theme='NO ONE BUT RĀMA',
 svg=svg('A devotee turning away from many paths to walk toward Rama with his bow and his brother Lakshmana',person(40,140,'#ff8c1a','#f2c79b',.6)+'<path d="M60 120 h60" stroke="#111" stroke-width="2"/><path d="M114 114 l8 6 l-8 6" fill="none" stroke="#111" stroke-width="2"/>'+person(150,140,'#2a9d6f','#2a9d6f',.65)+person(190,140,'#ffd60a','#f2c79b',.55)+BOW.replace('160','132')+lab(150,24,'SU-MUKHA · SU-HṚD · SU-LABHA',8),B),
 mean='Gracious of face, a true friend, easy to reach, giver of happiness, blessed with a good younger brother, handsome, whose arrow never misses: setting aside this best of the Raghus, I will never, ever, by any means, worship anyone else.',
 plain='Kind-faced, a true friend, easy to approach, giving joy, with a loyal brother, handsome, never missing His mark: I will never worship anyone but Rāma.',
 words=[('su-mukham','<b>gracious-faced</b>'),('su-hṛdam','<b>a true friend</b>'),('su-labham','<b>easy to reach</b>'),('sv-anujam','<b>with a good younger brother</b>'),('amogha-śaram','<b>whose arrow never fails</b>'),('na kathañcana','<b>never, by any means</b>')],
 deep='<p><b>Eight "su" words.</b> The verse strings together <i>su</i>- ("good") words: good face, good heart, easy to reach, good joy, good brother, good body. A pleasing sound pattern.</p><p><b>Sulabha.</b> "Easy to reach": for Śrīvaiṣṇavas, the Lord\'s <i>saulabhya</i>, His accessibility, matters as much as His greatness. Rāma befriended a boatman, a vulture, monkeys.</p><p><b>Ekānta bhakti.</b> "I will worship no other": single-minded devotion to one Lord.</p>',
 cards=('💡 Saulabhya','Accessibility: the great Lord is easy to approach.','💡 Lakṣmaṇa','Rāma\'s devoted younger brother: the "good brother" of this verse.'),
 inner='The greatest is also the easiest to reach. That is His greatness.',
 talk=('Why "easy to reach"?','Rāma was friends with a boatman, a vulture, a monkey army. Great but never distant: that\'s what devotees love.'),
 key='Kind, a friend, easy to reach: <b>no one but Rāma</b>.'),
D(n='9',lines=[['vinā veṅkaṭeśaṃ na nātho na nāthaḥ','sadā veṅkaṭeśaṃ smarāmi smarāmi |'],['hare veṅkaṭeśa prasīda prasīda','priyaṃ veṅkaṭeśa prayaccha prayaccha ‖9‖']],theme='NO LORD BUT VEṄKAṬEŚA',
 svg=svg('A devotee with folded hands repeating the name Venkatesa, with the name written again and again around him',person(110,140,'#ff8c1a','#f2c79b',.85)+''.join(lab(110+80*__import__("math").cos(k*.9),70+50*__import__("math").sin(k*.9),'VEṄKAṬEŚA',8) for k in range(7)),B),
 mean='Without Veṅkaṭeśa there is no lord, no lord! Always I remember Veṅkaṭeśa, I remember Him. O Hari, Veṅkaṭeśa, be pleased, be pleased! O Veṅkaṭeśa, grant what is dear, grant it!',
 plain='There is no master but Veṅkaṭeśa. I think of Him always. Lord, be kind to me; give me what is good, give it!',
 words=[('vinā','<b>without</b>'),('na nāthaḥ','<b>no lord</b>, no master'),('sadā smarāmi','<b>I always remember</b>'),('prasīda','<b>be pleased</b>, be gracious'),('priyam','<b>what is dear</b>'),('prayaccha','<b>grant!</b>')],
 deep='<p><b>Back to Veṅkaṭeśa.</b> After Kṛṣṇa and Rāma, the hymn returns to the Lord of the hills, by name, four times in one verse.</p><p><b>Twice over.</b> Every key word is doubled: <i>na nātho na nāthaḥ, smarāmi smarāmi, prasīda prasīda, prayaccha prayaccha</i>. It is the speech of someone pleading with all their heart.</p><p><b>A new metre.</b> Verses 9–10 are in <b>bhujaṅga-prayāta</b>, "the serpent\'s glide", with a rolling da-DUM-DUM rhythm. This is the best-known verse of the Stotram.</p>',
 cards=('💡 Bhujaṅgaprayāta','"Serpent\'s movement": a 12-syllable metre of four da-DUM-DUM beats.','💡 Smaraṇa','Remembering the Lord: one of the nine forms of bhakti.'),
 inner='Say His name twice when once is not enough.',
 talk=('Why say everything twice?','That\'s how we plead when it matters: please, please! The doubling makes it heartfelt.'),
 key='"Vinā veṅkaṭeśaṃ na nātho": <b>no lord but Veṅkaṭeśa</b>.'),
D(n='10',lines=[['ahaṃ dūratas te padāmbhojayugma-','praṇāmecchayāgatya sevāṃ karomi |'],['sakṛtsevayā nityasevāphalaṃ tvaṃ','prayaccha prayaccha prabho veṅkaṭeśa ‖10‖']],theme='ONE VISIT, ETERNAL SERVICE',
 svg=svg('A pilgrim with a walking stick and bundle arriving from a long road at the foot of the hills, bowing to the Lord\'s feet',HILL+TEMPLE(170,84)+'<path d="M0 150 q60 -10 120 -30" stroke="#c9a26b" stroke-width="10" fill="none"/>'+person(50,144,'#ff8c1a','#f2c79b',.55)+'<path d="M62 116 v30" stroke="#7a5a3a" stroke-width="3"/>'+lab(60,30,'FROM AFAR',11),B),
 mean='From far away I have come, longing to bow at Your two lotus feet, and I offer my service. For this one act of service, grant me the fruit of eternal service; grant it, grant it, O Lord Veṅkaṭeśa!',
 plain='I have come from far away to bow at Your feet and serve You. For this one visit, let me serve You forever, Lord Veṅkaṭeśa!',
 words=[('dūrataḥ','<b>from afar</b>'),('pada-ambhoja-yugma','<b>Your two lotus feet</b>'),('praṇāma-icchayā','<b>wishing to bow</b>'),('āgatya','<b>having come</b>'),('sakṛt-sevayā','<b>for one service</b>'),('nitya-sevā-phalam','<b>the fruit of eternal service</b>')],
 deep='<p><b>The pilgrim\'s prayer.</b> Every devotee who climbs the Seven Hills comes "from afar". This verse is their voice: I came, I bowed once; let that once become forever.</p><p><b>What is asked.</b> Not wealth or health but <i>nitya-sevā</i>, eternal service. The same wish as the devotees of Suprabhātam verse 19.</p><p><b>One for all.</b> One sincere moment of service can carry the fruit of a lifetime: that is the Lord\'s generosity of verse 4 again.</p>',
 cards=('💡 Sevā','Service to the Lord; also each ritual of worship in the temple.','💡 Yātrā','Pilgrimage: a journey to a holy place.'),
 inner='Make one sincere visit, and ask that it never end.',
 talk=('He came from far away?','Every pilgrim does! He asks: for this one visit, let me serve You forever.'),
 key='One visit, one bow: <b>grant me eternal service</b>.'),
D(n='11',lines=[['ajñāninā mayā doṣān','aśeṣān vihitān hare |'],['kṣamasva tvaṃ kṣamasva tvaṃ','śeṣaśailaśikhāmaṇe ‖11‖']],theme='FORGIVE ME',
 svg=svg('A devotee bowing fully on the ground before the hills, with a gentle light falling on them',HILL+'<path d="M140 30 l-40 100" stroke="#ffe9a0" stroke-width="16" opacity=".8"/>'+'<g stroke="#111" stroke-width="2.5"><ellipse cx="90" cy="146" rx="40" ry="7" fill="#ff8c1a"/><circle cx="46" cy="144" r="8" fill="#f2c79b"/></g>'+lab(110,24,'KṢAMASVA',12),B),
 mean='All the faults committed by me in my ignorance, O Hari: forgive them, You forgive them, O crest-jewel of Śeṣa hill.',
 plain='Lord, I don\'t know enough to avoid my mistakes. Please forgive all of them, forgive, O jewel of the hills.',
 words=[('ajñāninā mayā','<b>by me, ignorant</b>'),('doṣān','<b>faults</b>'),('aśeṣān','<b>all</b>, without remainder'),('vihitān','<b>committed</b>'),('kṣamasva','<b>forgive!</b>'),('śeṣa-śaila-śikhāmaṇe','<b>O crest-jewel of Śeṣa hill</b>')],
 deep='<p><b>Ending with forgiveness.</b> Most Hindu hymns end with a <i>kṣamā-prārthanā</i>, a prayer for forgiveness for any mistakes in worship. The Stotram does the same, in a short anuṣṭubh verse.</p><p><b>Aśeṣa and Śeṣa.</b> A gentle wordplay: forgive my faults <i>aśeṣān</i>, "without remainder", O jewel of the <i>Śeṣa</i> hill.</p><p><b>Said twice.</b> "Kṣamasva tvaṃ, kṣamasva tvaṃ": like verse 9, the plea is doubled.</p>',
 cards=('💡 Kṣamā-prārthanā','The closing prayer of forgiveness for mistakes in worship.','💡 Anuṣṭubh','The 8-syllable-line metre of the epics; also used for verses 1–2 of the Suprabhātam.'),
 inner='End every prayer by asking pardon. We never get it entirely right.',
 talk=('Why ask forgiveness at the end?','For every mistake, in life and in the prayer itself. It\'s a humble way to close.'),
 key='"Kṣamasva": <b>forgive all my faults, O Lord</b>.'),
]
